import{_ as a,o as t,c as i,au as o}from"./chunks/framework.DGGy0Y3v.js";const u=JSON.parse('{"title":"Migration Notes","description":"","frontmatter":{},"headers":[],"relativePath":"migration/index.md","filePath":"migration/index.md","lastUpdated":1793549075000}'),r={name:"migration/index.md"};function n(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="migration-notes" tabindex="-1">Migration Notes <a class="header-anchor" href="#migration-notes" aria-label="Permalink to &quot;Migration Notes&quot;">​</a></h1><p>Use this checklist when upgrading the package. The project is pre-1.0, so review the release&#39;s changelog before updating. These are current compatibility requirements, not a version-specific breaking-change history.</p><h2 id="runtime-and-assets" tabindex="-1">Runtime and assets <a class="header-anchor" href="#runtime-and-assets" aria-label="Permalink to &quot;Runtime and assets&quot;">​</a></h2><ul><li>Use Vue <code>^3.5.0</code>; components use Vue 3.5 APIs.</li><li>Import <code>vue-material-3/style.css</code> once. Component imports do not load CSS.</li><li>Load Roboto, Material Symbols Outlined, and legacy Material Icons, or self-host equivalent fonts.</li></ul><p>See <a href="/vue-material-3/guide/installation">Installation</a> for setup examples.</p><h2 id="models-and-forms" tabindex="-1">Models and forms <a class="header-anchor" href="#models-and-forms" aria-label="Permalink to &quot;Models and forms&quot;">​</a></h2><p>Use <code>v-model</code> for reactive parent-owned state. Text fields and selects retain legacy <code>value</code> support with different semantics: text-field <code>value</code> remains reactive when no model is supplied, while select <code>value</code> supplies the initial selection and reset baseline.</p><p>For range sliders, the model is <code>{ valueStart, valueEnd }</code>. Standalone date/time picker visibility is a separate <code>v-model:open</code>. Navigation drawers use <code>:opened</code> with <code>@change</code>.</p><p>Check the relevant component&#39;s API before changing existing bindings. Preserve accessible names and form labels when updating templates.</p><h2 id="verify-the-upgrade" tabindex="-1">Verify the upgrade <a class="header-anchor" href="#verify-the-upgrade" aria-label="Permalink to &quot;Verify the upgrade&quot;">​</a></h2><p>Exercise the states your application uses: disabled and readonly fields, validation, keyboard navigation, modal dismissal, and both color schemes. For changes to this repository, follow <a href="/vue-material-3/testing/browser">Browser and Package Checks</a>.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/vue-material-3/components/">Components</a></li><li><a href="/vue-material-3/api/">API Reference</a></li><li><a href="/vue-material-3/guide/theming">Theming</a></li><li><a href="https://mylmz10.github.io/vue-material-3/storybook/" target="_blank" rel="noreferrer">Storybook</a></li></ul>',13)])])}const p=a(r,[["render",n]]);export{u as __pageData,p as default};
